.graduate-ol-v26 {
    .graduate-ol-v26__list {
        width: 100%;
        margin-left: 0;
        max-width: initial;
    }

    .graduate-ol-v26__list__item {
        width: 100%;
        display: flex;
        flex-direction: row;
        gap: $measure--basic;
        border-bottom: $border-width-hairline $border-style-solid $color-gray2;
        padding-bottom: $measure--threequarters;

        &:last-child {
            border-bottom: none;
        }
    }

    .graduate-ol-v26__list__item__icon {
        align-self: center;
    }

    .graduate-ol-v26__list__item__content {
        display: flex;
        flex-direction: column;
    }

    .graduate-ol-v26__list__item__text {
        font-weight: $font-weight-bold;
    }

    .graduate-ol-v26__list__item__subtext {
        @include extrasmalltype();
        color: $color-gray7;
    }

    .graduate-ol-v26__small-print p {
        @include extrasmalltype();
        color: $color-gray7;
        font-style: italic;
    }
}
